CREATE OR REPLACE FUNCTION public.control_generar_cheques_pendientes(p_obra uuid, p_semana integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_cierre public.control_cierres_nomina%rowtype;
  v_item jsonb;
  v_trab public.trabajadores%rowtype;
  v_conc public.control_conciliacion_noi%rowtype;
  v_tipo text;
  v_metodo text;
  v_monto numeric;
  v_id uuid;
  v_insertados integer:=0;
begin
  if not (select public.app_ve_obra(p_obra)) or not (select public.app_puede_escribir()) then
    raise exception 'No tienes permiso para generar cheques en este centro de trabajo';
  end if;
  if p_semana not between 1 and 53 then raise exception 'Semana inválida'; end if;
  select * into v_cierre from public.control_cierres_nomina
   where obra_id=p_obra and semana=p_semana and estado<>'CANCELADO'
   order by created_at desc limit 1;
  if v_cierre.id is null then return 0; end if;
  for v_item in select value from jsonb_array_elements(coalesce(v_cierre.snapshot->'items','[]'::jsonb)) loop
    select * into v_trab from public.trabajadores where id=(v_item->>'trabajador_id')::uuid;
    if v_trab.id is null then continue; end if;
    -- Un alta/baja detectada permanece en revisión hasta documentar si hubo
    -- servicio. Sólo CON_SERVICIO permite un cheque automático.
    if exists (
      select 1 from public.control_altas_bajas_cortas a
      where a.obra_id=p_obra and a.trabajador_id=v_trab.id and a.semana=p_semana
        and a.anio=extract(year from coalesce(v_trab.fecha_baja::date,v_cierre.created_at::date))::integer
        and a.estado_servicio<>'CON_SERVICIO'
    ) then continue; end if;
    select * into v_conc from public.control_conciliacion_noi
     where cierre_id=v_cierre.id and trabajador_id=v_trab.id
       and tipo_calculo=coalesce(v_item->>'tipo','NOMINA') limit 1;
    v_tipo:=case when coalesce(v_item->>'tipo','NOMINA')='FINIQUITO' then 'FINIQUITO' else 'CHEQUE' end;
    v_metodo:=coalesce(v_conc.metodo_pago,v_item->>'metodo_pago',
      case when v_tipo='FINIQUITO' then 'CHEQUE'
           when length(regexp_replace(coalesce(v_trab.cuenta,''),'\D','','g'))<4
            and length(regexp_replace(coalesce(v_trab.clabe,''),'\D','','g'))<10 then 'CHEQUE'
           else 'TRANSFERENCIA' end);
    if v_tipo='FINIQUITO' and exists (
      select 1 from public.control_finiquitos_transferencia ft
       where ft.trabajador_id=v_trab.id and ft.obra_id=p_obra
         and ft.anio=extract(year from v_trab.fecha_baja::date)::integer and ft.semana=p_semana
    ) then continue; end if;
    if v_metodo<>'CHEQUE' then continue; end if;
    v_monto:=coalesce(v_conc.monto_noi,(v_item->>'monto')::numeric);
    if v_monto is null or v_monto<=0 then continue; end if;
    v_id:=null;
    select id into v_id from public.cheques
     where trabajador_id=v_trab.id and public.norm_semana(semana)=p_semana
       and tipo_pago=v_tipo and estatus<>'CANCELADO' and coalesce(eliminado,false)=false
     order by created_at limit 1;
    if v_id is null then
      insert into public.cheques(
        obra_id,trabajador_id,no_trab,contratista,nombre,puesto,curp,
        semana,periodo,importe,tipo_pago,estatus,observaciones,creado_por,
        cierre_id,origen_generacion)
      values (p_obra,v_trab.id,v_trab.no_trab,coalesce(v_trab.contratista,''),
        trim(concat_ws(' ',v_trab.primer_apellido,v_trab.segundo_apellido,v_trab.nombres)),
        coalesce(v_trab.puesto,''),coalesce(v_trab.curp,''),'S'||p_semana,
        coalesce(v_cierre.periodo,''),v_monto,v_tipo,'PENDIENTE',
        case when v_tipo='FINIQUITO' then 'GENERADO AUTOMÁTICAMENTE: FINIQUITO DEL CIERRE'
             else 'GENERADO AUTOMÁTICAMENTE: SIN CUENTA BANCARIA' end,
        coalesce(auth.jwt()->>'email','SISTEMA'),v_cierre.id,
        case when v_tipo='FINIQUITO' then 'FINIQUITO' else 'SIN_CUENTA' end)
      returning id into v_id;
      v_insertados:=v_insertados+1;
    end if;
    if v_conc.id is not null and v_cierre.estado in ('BORRADOR','REVISADO') then
      update public.control_conciliacion_noi set cheque_id=v_id,pago_id=null where id=v_conc.id;
    end if;
  end loop;
  return v_insertados;
end;
$function$

CREATE OR REPLACE FUNCTION public.control_transicion_cierre()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_actor uuid := (select auth.uid()); v_email text := coalesce(auth.jwt()->>'email',''); v_total int; v_pend int;
begin
  if new.obra_id is distinct from old.obra_id or new.semana is distinct from old.semana
     or new.periodo is distinct from old.periodo or new.creado_por is distinct from old.creado_por
     or new.created_at is distinct from old.created_at then
    raise exception 'La identidad y autoría del cierre son inmutables';
  end if;
  if new.estado is not distinct from old.estado and (
     new.revisado_por is distinct from old.revisado_por or new.autorizado_por is distinct from old.autorizado_por
     or new.timbrado_por is distinct from old.timbrado_por or new.pagado_por is distinct from old.pagado_por) then
    raise exception 'Los responsables de cada etapa solo se asignan mediante una transición válida';
  end if;
  if old.estado in ('AUTORIZADO','TIMBRADO','PAGADO','CANCELADO') then
    if new.snapshot is distinct from old.snapshot or new.snapshot_sha256 is distinct from old.snapshot_sha256
       or new.total_nomina is distinct from old.total_nomina or new.total_prevision is distinct from old.total_prevision
       or new.total_retenciones is distinct from old.total_retenciones or new.total_finiquitos is distinct from old.total_finiquitos
       or new.total_neto is distinct from old.total_neto or new.total_trabajadores is distinct from old.total_trabajadores then
      raise exception 'El cierre ya está bloqueado; sus importes y snapshot son inmutables';
    end if;
  end if;
  if new.estado is distinct from old.estado and new.estado in ('AUTORIZADO','CANCELADO')
     and not (select public.control_es_admin_cierre()) then
    raise exception 'Solo el administrador puede autorizar o cancelar un cierre' using errcode='42501';
  end if;
  if new.estado is distinct from old.estado then
    if not (
      (old.estado='BORRADOR' and new.estado in ('REVISADO','CANCELADO')) or
      (old.estado='REVISADO' and new.estado in ('BORRADOR','AUTORIZADO','CANCELADO')) or
      (old.estado='AUTORIZADO' and new.estado in ('TIMBRADO','CANCELADO')) or
      (old.estado='TIMBRADO' and new.estado='PAGADO')
    ) then raise exception 'Transición de cierre no permitida: % a %',old.estado,new.estado; end if;
    if new.estado='REVISADO' then
      if new.snapshot='{}'::jsonb or length(new.snapshot_sha256)<32 then raise exception 'El cierre requiere snapshot y huella antes de revisión'; end if;
      new.revisado_por=v_actor; new.revisado_por_email=v_email; new.revisado_en=now();
    elsif new.estado='AUTORIZADO' then
      if old.revisado_por is null or old.revisado_por=v_actor then raise exception 'La autorización requiere una segunda persona distinta de quien revisó'; end if;
      select count(*), count(*) filter(where estatus<>'COINCIDE') into v_total,v_pend
        from public.control_conciliacion_noi where cierre_id=old.id;
      if v_total=0 then raise exception 'Importa y concilia el reporte final de NOI antes de autorizar'; end if;
      if v_pend>0 then raise exception 'Existen % diferencias o trabajadores sin conciliar contra NOI',v_pend; end if;
      new.autorizado_por=v_actor; new.autorizado_por_email=v_email; new.autorizado_en=now(); new.bloqueado_en=now();
    elsif new.estado='TIMBRADO' then
      new.timbrado_por=v_actor; new.timbrado_por_email=v_email; new.timbrado_en=now();
    elsif new.estado='PAGADO' then
      new.pagado_por=v_actor; new.pagado_por_email=v_email; new.pagado_en=now();
    end if;
  end if;
  new.updated_at=now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.control_validar_neto_cheque_noi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cierre_id uuid;
  v_neto numeric;
  v_tipo text;
  v_cuantos integer;
begin
  if new.estatus not in ('EXPEDIDO','ENTREGADO')
     or coalesce(new.eliminado,false) then return new; end if;
  if tg_op='UPDATE' and old.estatus in ('EXPEDIDO','ENTREGADO')
     and (new.importe,new.trabajador_id,new.obra_id,new.semana,new.tipo_pago)
         is not distinct from
         (old.importe,old.trabajador_id,old.obra_id,old.semana,old.tipo_pago)
     then return new; end if;
  if new.trabajador_id is null or public.norm_semana(new.semana) is null then
    raise exception 'El cheque requiere trabajador y semana para comprobar el neto NOI';
  end if;
  select c.id into v_cierre_id
    from public.control_cierres_nomina c
   where c.obra_id=new.obra_id and c.semana=public.norm_semana(new.semana)
     and c.estado<>'CANCELADO' and c.archivo_noi is not null
   order by c.created_at desc limit 1;
  if v_cierre_id is null then return new; end if;
  v_tipo := case when new.tipo_pago='FINIQUITO' then 'FINIQUITO' else 'NOMINA' end;
  select count(*),max(n.monto_noi) into v_cuantos,v_neto
    from public.control_conciliacion_noi n
   where n.cierre_id=v_cierre_id and n.obra_id=new.obra_id
     and n.trabajador_id=new.trabajador_id and n.tipo_calculo=v_tipo;
  if v_cuantos<>1 or coalesce(v_neto,0)<=0 then
    raise exception 'No hay neto NOI positivo y único del tipo % para este cheque',v_tipo;
  end if;
  if new.importe is distinct from v_neto then
    raise exception 'Importe de cheque (%) distinto del neto NOI (%) para %',new.importe,v_neto,v_tipo;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.control_preparar_medio_pago()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_semana integer;
  v_periodo text;
  v_tipo text;
  v_cheque uuid;
  v_pago uuid;
  v_trab record;
begin
  if new.tipo_calculo='FINIQUITO' then
    new.metodo_pago='CHEQUE';
  end if;

  select c.semana,c.periodo into v_semana,v_periodo
  from public.control_cierres_nomina c where c.id=new.cierre_id;

  if new.metodo_pago='CHEQUE' and new.trabajador_id is not null and new.monto_noi is not null then
    v_tipo:=case when new.tipo_calculo='FINIQUITO' then 'FINIQUITO' else 'CHEQUE' end;
    select c.id into v_cheque
    from public.cheques c
    where c.trabajador_id=new.trabajador_id
      and public.norm_semana(c.semana)=v_semana
      and c.tipo_pago=v_tipo
      and c.estatus<>'CANCELADO'
      and coalesce(c.eliminado,false)=false
    order by c.created_at limit 1;

    if v_cheque is null then
      select t.* into v_trab from public.trabajadores t where t.id=new.trabajador_id;
      insert into public.cheques(
        obra_id,trabajador_id,no_trab,contratista,nombre,puesto,curp,
        semana,periodo,importe,tipo_pago,estatus,observaciones,creado_por,
        cierre_id,origen_generacion
      ) values (
        new.obra_id,new.trabajador_id,new.trabajador_numero,coalesce(v_trab.contratista,''),
        new.trabajador_nombre,coalesce(v_trab.puesto,''),coalesce(v_trab.curp,''),
        'S'||v_semana,coalesce(v_periodo,''),new.monto_noi,v_tipo,'PENDIENTE',
        case when new.tipo_calculo='FINIQUITO'
             then 'GENERADO AUTOMÁTICAMENTE: FINIQUITO CONCILIADO CONTRA NOI'
             else 'GENERADO AUTOMÁTICAMENTE: TRABAJADOR SIN CUENTA / MÉTODO CHEQUE' end,
        coalesce(auth.jwt()->>'email','SISTEMA'),new.cierre_id,
        case when new.tipo_calculo='FINIQUITO' then 'FINIQUITO' else 'CIERRE_NOI' end
      ) returning id into v_cheque;
    else
      update public.cheques
      set importe=new.monto_noi,
          updated_at=now()
      where id=v_cheque and estatus='PENDIENTE' and coalesce(num_cheque,'')='';
    end if;
    new.cheque_id=v_cheque;
    new.pago_id=null;
  elsif new.metodo_pago='TRANSFERENCIA' and new.trabajador_id is not null then
    select p.id into v_pago
    from public.pagos p
    where p.obra_id=new.obra_id
      and p.trabajador_id=new.trabajador_id
      and public.norm_semana(p.semana)=v_semana
      and upper(coalesce(p.estado,'')) not in ('RECHAZADO','CANCELADO','DEVUELTO')
    order by case when new.monto_noi is not null and abs(coalesce(p.importe,0)-new.monto_noi)<=0.01 then 0 else 1 end,
             p.created_at desc
    limit 1;
    new.pago_id=v_pago;
    new.cheque_id=null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.control_validar_conciliacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_estado text;
begin
  select estado into v_estado from public.control_cierres_nomina where id=coalesce(new.cierre_id,old.cierre_id);
  if v_estado in ('AUTORIZADO','TIMBRADO','PAGADO','CANCELADO') then
    raise exception 'La conciliación de un cierre autorizado, timbrado, pagado o cancelado es inmutable';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.control_eliminar_cierre_admin(p_cierre_id uuid, p_confirmacion text, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cierre public.control_cierres_nomina%rowtype;
  v_email text;
  v_noi jsonb;
  v_cheques jsonb;
begin
  if (select auth.uid()) is null or not (select public.control_es_admin_cierre()) then
    raise exception 'Sólo el administrador autorizado puede eliminar un cierre';
  end if;
  select * into v_cierre from public.control_cierres_nomina
  where id=p_cierre_id for update;
  if not found then raise exception 'Cierre no encontrado'; end if;
  if p_confirmacion is distinct from 'ELIMINAR S'||v_cierre.semana::text then
    raise exception 'La segunda confirmación no coincide con la semana';
  end if;
  if length(btrim(coalesce(p_motivo,'')))<10 then
    raise exception 'Indica un motivo de al menos 10 caracteres';
  end if;
  select u.email into v_email from public.app_usuarios u where u.user_id=(select auth.uid());
  select coalesce(jsonb_agg(to_jsonb(n) order by n.created_at,n.id),'[]'::jsonb)
    into v_noi from public.control_conciliacion_noi n where n.cierre_id=p_cierre_id;
  select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at,q.id),'[]'::jsonb)
    into v_cheques from public.cheques q where q.cierre_id=p_cierre_id;

  insert into public.control_cierres_eliminados
    (id,obra_id,semana,periodo,estado_anterior,snapshot_sha256,cierre,
     conciliacion,cheques_vinculados,motivo,actor_id,actor_email)
  values (v_cierre.id,v_cierre.obra_id,v_cierre.semana,v_cierre.periodo,
          v_cierre.estado,v_cierre.snapshot_sha256,to_jsonb(v_cierre),
          v_noi,v_cheques,btrim(p_motivo),(select auth.uid()),v_email);

  perform set_config('app.cierre_admin_delete_id',p_cierre_id::text,true);
  delete from public.control_cierres_nomina where id=p_cierre_id;

  insert into public.control_bitacora
    (obra_id,modulo,accion,entidad_tipo,entidad_id,detalle,actor_id,actor_email)
  values (v_cierre.obra_id,'CIERRE_NOMINA','ELIMINAR_ADMIN','CIERRE',v_cierre.id,
    jsonb_build_object('semana',v_cierre.semana,'periodo',v_cierre.periodo,
      'estado_anterior',v_cierre.estado,'huella',v_cierre.snapshot_sha256,
      'filas_noi',jsonb_array_length(v_noi),'cheques_vinculados',jsonb_array_length(v_cheques),
      'motivo',btrim(p_motivo)),(select auth.uid()),v_email);

  return jsonb_build_object('id',v_cierre.id,'semana',v_cierre.semana,
    'archivo_id',v_cierre.id,'filas_noi_archivadas',jsonb_array_length(v_noi),
    'cheques_conservados',jsonb_array_length(v_cheques));
end;
$function$

CREATE OR REPLACE FUNCTION public.control_proteger_papelera_cheques()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (new.eliminado,new.eliminado_por,new.eliminado_en,new.motivo_eliminado)
    is not distinct from
    (old.eliminado,old.eliminado_por,old.eliminado_en,old.motivo_eliminado)
    then return new; end if;
  -- Las tareas internas mantienen su acceso; nunca se admite un usuario anónimo.
  if (select auth.uid()) is null and current_user in ('postgres','service_role') then
    return new;
  end if;
  if public.control_es_admin_cierre() then return new; end if;
  if not public.control_puede_eliminar_cheques()
     or not public.app_ve_obra(old.obra_id) then
    raise exception 'No tienes permiso para eliminar cheques' using errcode='42501';
  end if;
  if coalesce(old.eliminado,false) or not coalesce(new.eliminado,false) then
    raise exception 'Solo el administrador puede restaurar o modificar un cheque eliminado' using errcode='42501';
  end if;
  if (to_jsonb(new)-array['eliminado','eliminado_por','eliminado_en','motivo_eliminado','updated_at','actualizado_por'])
    is distinct from
    (to_jsonb(old)-array['eliminado','eliminado_por','eliminado_en','motivo_eliminado','updated_at','actualizado_por']) then
    raise exception 'Este permiso solo permite mover el cheque a la papelera' using errcode='42501';
  end if;
  if nullif(btrim(new.motivo_eliminado),'') is null then
    raise exception 'Indica el motivo de eliminación';
  end if;
  new.eliminado_por:=auth.email();
  new.eliminado_en:=now();
  return new;
end;
$function$
